section.sourcecode:
typedef   signed char  int8; /* ちょうど8ビット幅の符号付き整数 */
typedef unsigned char uint8; /* 符号なしの同上 */

typedef short int16;         /* ちょうど16ビット幅の符号付き整数 */
typedef unsigned int16 uint16; /* 符号なしの同上 */
/* int32は少なくとも32ビット幅の符号付き整数型 */

typedef long int32; /* すべてのシステムで動作が保証されます */
typedef int  int32; /* 一部のシステムではより効率的です */

typedef unsigned int32 uint32;

/* 少なくとも16ビット幅の符号なし整数型。正確なサイズは、
   使用しているプロセッサーにとって最も都合のよいもの */

typedef unsigned int uint;

/* ピクセル自体は8ビットの符号なし整数ですが、ピクセルの演算は
   16ビットまたは32ビットの精度で行われることが多く、その結果を
   8ビットの範囲に「飽和」させる、つまりクランプする必要があります。 */

typedef uint8 Pixel;

Pixel clamp255(int32 v) { return v < 0? 0 : (v < 255? v : 255);}

/*  以下のbool_decoderの説明で詳しく述べるように、VP8は確率を
    8ビットの符号なし数値で表します。 */

typedef uint8 Prob;

/* まずエンコーダー */

typedef struct {
  uint8 *output;  /* 次に書き込むバイトへのポインター */
  uint32 range;   /* 128 <= range <= 255 */
  uint32 bottom;  /* 残りの出力の最小値 */
  int bit_count;  /* 出力バイトが得られるまでの
                     シフト回数 */
} bool_encoder;

/* ブール値を書き込む前に、エンコーダーの初期状態を設定しなければ
   なりません。 */

void init_bool_encoder(bool_encoder *e, uint8 *start_partition)
{
  e->output = start_partition;
  e->range = 255;
  e->bottom = 0;
  e->bit_count = 24;
}

/* 符号化では、ごくまれに、すでに書き込んだ出力へ伝播させなければ
   ならない桁上がりが発生します。この伝播が出力の先頭を越えることは
   決してないことが、算術的に保証されています。言い換えれば、
   符号化された値xは常に1未満です。 */

void add_one_to_output(uint8 *q)
{
  while (*--q == 255)
    *q = 0;
  ++*q;
}

/* 0になる確率がprob/256である（と期待される）bool_valueを書き込む
   メイン関数です。 */

void write_bool(bool_encoder *e, Prob prob, int bool_value)
{
  /* splitはおよそ(range * prob) / 256であり、重要なことに、
     0より真に大きく、rangeより真に小さくなります */

  uint32 split = 1 + (((e->range - 1) * prob) >> 8);
  if (bool_value) {
    e->bottom += split; /* 区間の下端を上に移動し */
    e->range -= split;  /* それに応じてrangeを縮小 */
  } else
    e->range = split;   /* bottomはそのままでrangeを縮小 */

  while (e->range < 128)
  {
    e->range <<= 1;

    if (e->bottom & (1 << 31))  /* 桁上がりを検出 */
      add_one_to_output(e->output);

    e->bottom <<= 1;        /* （bottomをシフトする前に） */

    if (!--e->bit_count) {  /* bottomの上位バイトを書き出し ... */

      *e->output++ = (uint8) (e->bottom >> 24);

      e->bottom &= (1 << 24) - 1;  /* ... 下位3バイトを残す */

      e->bit_count = 8;            /* 次の出力まで8回シフト */
    }
  }
}

/* 書き込み中のパーティションの最後のブール値を符号化した後に、
   この関数を（ちょうど1回）呼び出します */

void flush_bool_encoder(bool_encoder *e)
{
  int c = e->bit_count;
  uint32 v = e->bottom;

  if (v & (1 << (32 - c)))   /* （まれな）桁上がりを伝播させてから */
    add_one_to_output(e->output);
  v <<= c & 7;               /* 残りの出力を */
  c >>= 3;                   /* 内部バッファーの先頭へシフト */
  while (--c >= 0)
    v <<= 8;
  c = 4;
  while (--c >= 0) {    /* 残りを書き出す（パディング付きの場合も） */
    *e->output++ = (uint8) (v >> 24);
    v <<= 8;
  }
}
/* デコーダーの状態はエンコーダーの状態とまったく対応しています。
   「value」と残りの入力を合わせたものは、符号化された数x全体から
   現在の符号化区間の左端点を引いたものに等しくなります。 */

typedef struct {
  uint8   *input;     /* 次の圧縮データバイトへのポインター */
  uint32  range;      /* 常にエンコーダーのrangeと同一 */
  uint32  value;      /* 少なくとも8ビットの有効ビットを含む */
  int     bit_count;  /* valueからシフトアウトしたビット数
                         （最大7） */
} bool_decoder;

/* パーティションからブール値を読み込む前に、この関数を呼び出します。 */

void init_bool_decoder(bool_decoder *d, uint8 *start_partition)
{
  {
    int i = 0;
    d->value = 0;           /* value = 最初の2入力バイト */
    while (++i <= 2)

      d->value = (d->value << 8)  |  *start_partition++;
  }

  d->input = start_partition;  /* 次に読み込むバイトへのポインター */
  d->range = 255;           /* 初期rangeは全範囲 */
  d->bit_count = 0;         /* まだ1ビットもシフトアウトしていない */
}

/* 確率prob/256で符号化されたブール値を読み込むメイン関数です。
   この確率は、当然ながら、そのブール値を書き込んだときに使った
   確率と一致しなければなりません。 */

int read_bool(bool_decoder *d, Prob prob)
{
  /* rangeとsplitは、このブール値を書き込んだときにエンコーダーが
     使った対応する値と同一です */

  uint32  split = 1 + (((d->range - 1) * prob) >> 8);
  uint32  SPLIT = split << 8;
  int     retval;           /* 0または1になる */
  if (d->value >= SPLIT) {  /* 1が符号化されていた */
    retval = 1;
    d->range -= split;  /* rangeを縮小 */
    d->value -= SPLIT;  /* 区間の左端点を差し引く */
  } else {              /* 0が符号化されていた */
    retval = 0;
    d->range = split;  /* rangeを縮小、左端点は変更なし */
  }

  while (d->range < 128) {  /* 無関係なvalueのビットをシフトアウト */
    d->value <<= 1;
    d->range <<= 1;
    if (++d->bit_count == 8) {  /* 新しいビットを8ビットずつシフトイン */
      d->bit_count = 0;
      d->value |= *d->input++;
    }
  }
  return retval;
}

/* 「リテラル」、つまり、各ビットが確率128（すなわち1/2）で符号化
   され、ビットが上位から下位の順に並ぶ「num_bits」幅の符号なし値を
   読み込む便利関数です。 */

uint32 read_literal(bool_decoder *d, int num_bits)
{
  uint32 v = 0;

  while (num_bits--)
    v = (v << 1) + read_bool(d, 128);
  return v;
}

/* 符号付きの数を読み込む変種 */

int32 read_signed_literal(bool_decoder *d, int num_bits)
{
  int32 v = 0;
  if (!num_bits)
    return 0;
  if (read_bool(d, 128))
    v = -1;
  while (--num_bits)
    v = (v << 1) + read_bool(d, 128);
  return v;
}

/* ツリーの仕様は単なる8ビット整数の配列です。 */

typedef int8 tree_index;
typedef const tree_index Tree[];

/* デコーダーの現在の位置にあるツリー符号化された値を読み込んで
   返します。 */

int treed_read(
  bool_decoder * const d, /* bool_decoderは常に0か1を返す */
  Tree t,                 /* ツリーの仕様 */
  const Prob p[]     /* 対応する内部ノードの確率 */
) {
  register tree_index i = 0;   /* ルートから開始 */

  /* 葉に到達するまでツリーを下る */

  while ((i = t[ i + read_bool(d, p[i>>1])]) > 0) {}

  return -i;     /* 戻り値は非正のインデックスの符号を反転したもの */
}

typedef enum
{
    DC_PRED, /* 上の行と左の列を使ってDCを予測 */
    V_PRED,  /* 上の行を使って各行を予測 */
    H_PRED,  /* 左の列を使って各列を予測 */
    TM_PRED, /* 「True Motion」風に2階差分を伝播 */

    B_PRED,  /* 各Yサブブロックを独立に予測 */

    num_uv_modes = B_PRED,  /* 最初の4つのモードは色差に適用 */
    num_ymodes   /* すべてのモードは輝度に適用 */
}
intra_mbmode;

/* 前述のツリーと、それが意味する符号をコメントとして示します。
   実際の（すなわち正の）インデックスは常に偶数です。
   値の（すなわち非正の）インデックスは任意です。 */

const tree_index ymode_tree [2 * (num_ymodes - 1)] =
{
 -DC_PRED, 2,        /* ルート: DC_PRED = "0"、"1"のサブツリー */
  4, 6,              /* "1"のサブツリーは2つの子孫サブツリーを持つ */
   -V_PRED, -H_PRED, /* "10"のサブツリー: V_PRED = "100"、
                        H_PRED = "101" */
   -TM_PRED, -B_PRED /* "11"のサブツリー: TM_PRED = "110"、
                        B_PRED = "111" */
};

const tree_index kf_ymode_tree [2 * (num_ymodes - 1)] =
{
 -B_PRED, 2,            /* ルート: B_PRED = "0"、"1"のサブツリー */
  4, 6,                 /* "1"のサブツリーは2つの子孫サブツリーを持つ */
   -DC_PRED, -V_PRED,   /* "10"のサブツリー: DC_PRED = "100"、
                           V_PRED = "101" */
   -H_PRED, -TM_PRED    /* "11"のサブツリー: H_PRED = "110"、
                           TM_PRED = "111" */
};
const tree_index uv_mode_tree [2 * (num_uv_modes - 1)] =
{
 -DC_PRED, 2,          /* ルート: DC_PRED = "0"、"1"のサブツリー */
  -V_PRED, 4,          /* "1"のサブツリー: V_PRED = "10"、
                          "11"のサブツリー */
   -H_PRED, -TM_PRED   /* "11"のサブツリー: H_PRED = "110"、
                          TM_PRED = "111" */
};

/* bool_decoder dが与えられたとき、Yモードは次のように復号できます。 */

const Prob pretend_its_huffman [num_ymodes - 1] =
  { 128, 128, 128, 128};

Ymode = (intra_mbmode) treed_read(d, ymode_tree,
  pretend_its_huffman);

unsigned char *c = pbi->source+3;

// 同期コードで検査
if (c[0]!=0x9d||c[1]!=0x01||c[2]!=0x2a)
    return -1;

pc->Width      = swap2(*(unsigned short*)(c+3))&0x3fff;
pc->horiz_scale = swap2(*(unsigned short*)(c+3))>>14;
pc->Height     = swap2(*(unsigned short*)(c+5))&0x3fff;
pc->vert_scale  = swap2(*(unsigned short*)(c+5))>>14;

const tree_index mb_segment_tree [2 * (4-1)] =
  {
    2,  4,     /* ルート："0"、"1"のサブツリー */
    -0, -1,    /* "00" = 0番目の値、"01" = 1番目の値 */
     -2, -3    /* "10" = 2番目の値、"11" = 3番目の値 */
  }

typedef enum
{
    DC_PRED, /* 上の行と左の列を使って DC を予測 */
    V_PRED,  /* 上の行を使って各行を予測 */
    H_PRED,  /* 左の列を使って各列を予測 */
    TM_PRED, /* "True Motion" 風に 2 階差分を伝播 */

    B_PRED,  /* 各 Y サブブロックを独立に予測 */

    num_uv_modes = B_PRED,  /* 最初の 4 つのモードは色差に適用 */
    num_ymodes   /* すべてのモードは輝度に適用 */
}
intra_mbmode;

const tree_index kf_ymode_tree [2 * (num_ymodes - 1)] =
{
 -B_PRED, 2,            /* ルート: B_PRED = "0"、"1" サブツリー */
  4, 6,                 /* "1" サブツリーの下に子サブツリーが 2 つ */
   -DC_PRED, -V_PRED,   /* "10" サブツリー: DC_PRED = "100"、
                           V_PRED = "101" */
   -H_PRED, -TM_PRED    /* "11" サブツリー: H_PRED = "110"、
                           TM_PRED = "111" */
};

typedef enum { B_DC_PRED, /* 上の行と左の列を使って DC を予測 */ B_TM_PRED, /* "True Motion" 風に 2 階差分を伝播 */
B_VE_PRED, /* 上の行を使って各行を予測 */ B_HE_PRED, /* 左の列を使って各列を予測 */
B_LD_PRED, /* 南西（左下）方向の 45 度の対角予測 */ B_RD_PRED, /* 南東（右下）方向の "" */
B_VR_PRED, /* SSE（垂直右）方向の対角予測 */ B_VL_PRED, /* SSW（垂直左）方向の "" */ B_HD_PRED, /* ESE（水平下）方向の "" */ B_HU_PRED, /* ENE（水平上）方向の "" */
num_intra_bmodes } intra_bmode;
/* 上記の符号化ツリー。対応する符号をコメントに記載 */
const tree_index bmode_tree [2 * (num_intra_bmodes - 1)] = { -B_DC_PRED, 2, /* B_DC_PRED = "0" */ -B_TM_PRED, 4, /* B_TM_PRED = "10" */ -B_VE_PRED, 6, /* B_VE_PRED = "110" */ 8, 12, -B_HE_PRED, 10, /* B_HE_PRED = "11100" */ -B_RD_PRED, -B_VR_PRED, /* B_RD_PRED = "111010", B_VR_PRED = "111011" */ -B_LD_PRED, 14, /* B_LD_PRED = "111110" */ -B_VL_PRED, 16, /* B_VL_PRED = "1111110" */ -B_HD_PRED, -B_HU_PRED /* HD = "11111110", HU = "11111111" */ };

const tree_index uv_mode_tree [2 * (num_uv_modes - 1)] =
{
 -DC_PRED, 2,           /* ルート: DC_PRED = "0"、"1" サブツリー */
  -V_PRED, 4,           /* "1" サブツリー:  V_PRED = "10"、
                           "11" サブツリー */
   -H_PRED, -TM_PRED    /* "11" サブツリー: H_PRED = "110"、
                           TM_PRED = "111" */
};

const Prob kf_uv_mode_prob [num_uv_modes - 1] = { 142, 114, 183};
uv_mode = (intra_mbmode) treed_read(d, uv_mode_tree,
  kf_uv_mode_prob);

int sum;  /* 8 または 16 ピクセルの和（少なくとも 16 ビット精度） */
int shf;  /* ピクセル数の 2 を底とする対数（3 または 4） */

Pixel DCvalue = (sum + (1 << (shf-1))) >> shf;

void TMpred(
    Pixel b[8][8],      /* 色差（U または V）の予測ブロック */
    const Pixel A[8],   /* ブロックの上にある構築済みピクセルの行 */
    const Pixel L[8],   /* ブロックのすぐ左にある "" の列 */
    const Pixel P       /* A のすぐ左、L のすぐ上にあるピクセル */
) {
    int r = 0;          /* 行 */
    do {
        int c = 0;      /* 列 */
        do {
            b[r][c] = clamp255(L[r]+ A[c] - P);
        } while (++c < 8);
    } while (++r < 8);
}

/* 結果のピクセルは、2 つまたは 3 つの予測値ピクセルの平均で
   あることがよくあります。以下のサブルーチンは、これらの平均
   を計算するのに使います。引数は有効なピクセルなので、
   クランプは必要ありません。実際の実装では、おそらく
   インライン関数かマクロを使うでしょう。 */

/* y を中心とし、隣接する x、z との加重平均を計算 */

Pixel avg3(Pixel x, Pixel y, Pixel z) {
  return (x + y + y + z + 2) >> 2;}

/* p を中心とする隣接 3 ピクセルの加重平均 */

Pixel avg3p(const Pixel *p) { return avg3(p[-1], p[0], p[1]);}

/* x と y の単純平均 */

Pixel avg2(Pixel x, Pixel y) { return (x + y + 1) >> 1;}

/* p[0] と p[1] の平均は、2 つの間にある合成ピクセル、つまり
   p から半ステップ進んだ位置のピクセルとみなせます。 */

Pixel avg2p(const Pixel *p) { return avg2(p[0], p[1]);}

void subblock_intra_predict(
    Pixel B[4][4],     /* Y サブブロックの予測バッファー */
    const Pixel *A,    /* A[0]...A[7] = 上の行、A[-1] = P */
    const Pixel *L,    /* L[0]...L[3] = 左の列、L[-1] = P */
    intra_bmode mode   /* 列挙型はセクション11.2を参照 */
) {
    Pixel E[9];        /* 構築済みのエッジピクセル 9 個 */
    E[0] = L[3];  E[1] = L[2];  E[2] = L[1];  E[3] = L[0];
    E[4] = A[-1];      /* == L[-1] == P */
    E[5] = A[0];  E[6] = A[1];  E[7] = A[2];  E[8] = A[3];

  switch(mode) {
    /* 最初の 4 つのモードは、対応するブロック全体のモードと
       似ています。 */

    case B_DC_PRED:
    {
        int v = 4;      /* DC の和/平均。4 は丸めの調整 */
        int i = 0;  do { v += A[i] + L[i];}  while (++i < 4);
        v >>= 3;        /* 8 ピクセルの平均 */
        i = 0;  do {    /* 予測バッファーを定数の DC 値で埋めます */
            int j = 0;  do { B[i][j] = v;}  while (++j < 4);
        } while (++i < 4);
        break;
    }

    case B_TM_PRED: /* 16x16 の TM_PRED とまったく同じ */
    {
        int r = 0;  do {
            int c = 0;  do {
                B[r][c] = clamp255(L[r] + A[c] - A[-1]);
            } while (++c < 4);
        } while (++r < 4);
        break;
    }

    case B_VE_PRED: /* 平均を使う点を除いて 16x16 の V_PRED と同様 */
    {
        int c = 0;  do { /* 4 行すべて = 平滑化した上の行 */
            B[0][c] = B[1][c] = B[2][c] = B[3][c] = avg3p(A + c);
        } while (++c < 4);
        break;
    }

    case B_HE_PRED: /* 平均を使う点を除いて 16x16 の H_PRED と同様 */
    {
        /* L[4] が存在しないので、最下行は例外 */
        int v = avg3(L[2], L[3], L[3]);
        int r = 3;  while (1) {  /* 4 列すべて = 平滑化した左の列 */
            B[r][0] = B[r][1] = B[r][2] = B[r][3] = v;
            if (--r < 0)
                break;
            v = avg3p(L + r);  /* 上の 3 行は 3 ピクセルの平均を使用 */
        }
        break;
    }

    /* 残る 6 つの「対角」モードは、予測バッファーを対角線に
       分割します。各線上のピクセルにはすべて同じ値を割り当て
       ます。この値は、同じ線上にある構築済みの予測値（を
       平滑化したもの、または合成したもの）です。わかりやすさ
       のため、コメントでは、これらの予測値ピクセルの位置を、
       出力先の配列 B の左上隅からの相対位置で表します。
       これらのモードはサブブロック予測に固有のもので、ブロック
       全体のモードに相当するものはありません。最初の 2 つは、
       水平（または同じことですが垂直）から +|- 45 度の線、
       つまり傾きが +|- 1 の線を使います。 */

    case B_LD_PRED:    /* 南西（左下）方向。ステップ =
                          (-1, 1) または (1,-1) */
        /* avg3p(A + j) は (-1,j) にある「平滑化した」ピクセル */
        B[0][0] = avg3p(A + 1);
        B[0][1] = B[1][0] = avg3p(A + 2);
        B[0][2] = B[1][1] = B[2][0] = avg3p(A + 3);
        B[0][3] = B[1][2] = B[2][1] = B[3][0] = avg3p(A + 4);
        B[1][3] = B[2][2] = B[3][1] = avg3p(A + 5);
        B[2][3] = B[3][2] = avg3p(A + 6);
        B[3][3] = avg3(A[6], A[7], A[7]); /* A[8] は存在しません */
        break;

    case B_RD_PRED: /* 南東（右下）方向。ステップ =
                       (1,1) または (-1,-1) */
        B[3][0] = avg3p(E + 1);  /* 予測値は (2, -1) から */
        B[3][1] = B[2][0] = avg3p(E + 2);  /* (1, -1) */
        B[3][2] = B[2][1] = B[1][0] = avg3p(E + 3);  /* (0, -1) */
        B[3][3] = B[2][2] = B[1][1] = B[0][0] =
          avg3p(E + 4);  /* (-1, -1) */
        B[2][3] = B[1][2] = B[0][1] = avg3p(E + 5);  /* (-1, 0) */
        B[1][3] = B[0][2] = avg3p(E + 6);  /* (-1, 1) */
        B[0][3] = avg3p(E + 7);  /* (-1, 2) */
        break;

    /* 残る 4 つの対角モードは、傾きが +|- 2 と +|- 1/2 の線を
       使います。これらの線の角度は、水平または垂直からおよそ
       +|- 27 度です。

       45 度の対角線と異なり、ここでは avg2p(p) を使って、2 つの
       実際の予測値の中間にある予測値ピクセルを「合成」する必要
       がよくあります。avg2p(p) は p[1/2] の「位置にある」
       ピクセルを返すものと考えます。 */

    case B_VR_PRED:    /* SSE（垂直右）方向。ステップ =
                          (2,1) または (-2,-1) */
        B[3][0] = avg3p(E + 2);  /* 予測値は (1, -1) から */
        B[2][0] = avg3p(E + 3);  /* (0, -1) */
        B[3][1] = B[1][0] = avg3p(E + 4);  /* (-1,   -1) */
        B[2][1] = B[0][0] = avg2p(E + 4);  /* (-1, -1/2) */
        B[3][2] = B[1][1] = avg3p(E + 5);  /* (-1,    0) */
        B[2][2] = B[0][1] = avg2p(E + 5);  /* (-1,  1/2) */
        B[3][3] = B[1][2] = avg3p(E + 6);  /* (-1,    1) */
        B[2][3] = B[0][2] = avg2p(E + 6);  /* (-1,  3/2) */
        B[1][3] = avg3p(E + 7);  /* (-1, 2) */
        B[0][3] = avg2p(E + 7);  /* (-1, 5/2) */
        break;

    case B_VL_PRED:    /* SSW（垂直左）方向。ステップ =
                          (2,-1) または (-2,1) */
        B[0][0] = avg2p(A);  /* 予測値は (-1, 1/2) から */
        B[1][0] = avg3p(A + 1);  /* (-1, 1) */
        B[2][0] = B[0][1] = avg2p(A + 1);  /* (-1, 3/2) */
        B[1][1] = B[3][0] = avg3p(A + 2);  /* (-1,   2) */
        B[2][1] = B[0][2] = avg2p(A + 2);  /* (-1, 5/2) */
        B[3][1] = B[1][2] = avg3p(A + 3);  /* (-1,   3) */
        B[2][2] = B[0][3] = avg2p(A + 3);  /* (-1, 7/2) */
        B[3][2] = B[1][3] = avg3p(A + 4);  /* (-1,   4) */
        /* 最後の 2 つの値は厳密にはパターンに従いません。 */
        B[2][3] = avg3p(A + 5);  /* (-1, 5) [avg2p(A + 4) =
                                     (-1,9/2)] */
        B[3][3] = avg3p(A + 6);  /* (-1, 6) [avg3p(A + 5) =
                                     (-1,5)] */
        break;

    case B_HD_PRED:    /* ESE（水平下）方向。ステップ =
                          (1,2) または (-1,-2) */
        B[3][0] = avg2p(E);  /* 予測値は (5/2, -1) から */
        B[3][1] = avg3p(E + 1);  /* (2, -1) */
        B[2][0] = B[3][2] = svg2p(E + 1);  /* ( 3/2, -1) */
        B[2][1] = B[3][3] = avg3p(E + 2);  /* (   1, -1) */
        B[2][2] = B[1][0] = avg2p(E + 2);  /* ( 1/2, -1) */
        B[2][3] = B[1][1] = avg3p(E + 3);  /* (   0, -1) */
        B[1][2] = B[0][0] = avg2p(E + 3);  /* (-1/2, -1) */
        B[1][3] = B[0][1] = avg3p(E + 4);  /* (  -1, -1) */
        B[0][2] = avg3p(E + 5);  /* (-1, 0) */
        B[0][3] = avg3p(E + 6);  /* (-1, 1) */
        break;

    case B_HU_PRED:    /* ENE（水平上）方向。ステップ = (1,-2)
                          または (-1,2) */
        B[0][0] = avg2p(L);  /* 予測値は (1/2, -1) から */
        B[0][1] = avg3p(L + 1);  /* (1, -1) */
        B[0][2] = B[1][0] = avg2p(L + 1);  /* (3/2, -1) */
        B[0][3] = B[1][1] = avg3p(L + 2);  /* (  2, -1) */
        B[1][2] = B[2][0] = avg2p(L + 2);  /* (5/2, -1) */
        B[1][3] = B[2][1] = avg3(L[2], L[3], L[3]);  /* (3, -1) */
        /* 最下行の大部分では、該当する対角線上に（近くの）
           構築済みピクセルがないため、パターンに従うことが
           できません。 */
        B[2][2] = B[2][3] = B[3][0] = B[3][1] = B[3][2] = B[3][3]
          = L[3];
  }
}

uint DCTextra(bool_decoder *d, const Prob *p)
{
    uint v = 0;
    do { v += v + read_bool(d, *p);}  while (*++p);
    return v;
}

const Prob Pcat1[] = { 159, 0};
const Prob Pcat2[] = { 165, 145, 0};
const Prob Pcat3[] = { 173, 148, 140, 0};
const Prob Pcat4[] = { 176, 155, 140, 135, 0};
const Prob Pcat5[] = { 180, 157, 141, 134, 130, 0};
const Prob Pcat6[] =
    { 254, 254, 243, 230, 196, 177, 153, 140, 133, 130, 129, 0};

int block[16] = { 0 }; /* 現在の4x4ブロックの係数 */
int firstCoeff = 0;
int plane;
int ctx2;
int ctx3 = 0; /* 上記の説明で述べた3番目のコンテキスト */
Prob *probTable;
int token;
int sign;
int absValue;
int extraBits;
bool prevCoeffWasZero = false;
bool currentBlockHasCoeffs = false;
/* カテゴリーごとの係数の絶対値の基点。要素 #0 は DCT_VAL_CATEGORY1、
   #1 は DCT_VAL_CATEGORY2、以下同様。 */
int categoryBase[6] = { 5, 7, 11, 19, 35, 67 };

/* 使用するプレーンを決定 */
if ( **current_block_is_Y2_block** )       plane = 0;
else if ( **current_block_is_chroma** )   plane = 2;
else if ( **current_macroblock_has_Y2** ) plane = 1;
else                                      plane = 3;

/* 「Y2マクロブロック」の輝度ブロックでは係数インデックス #0 を飛ばす */
if ( plane == 1 )
    firstCoeff++;

/* 近隣の4x4ブロックが係数を持つかどうかを決定します。これは現在
   デコードしているプレーンに依存します。つまり、現在のブロックと
   同じプレーンの係数だけを調べます。 */
if ( **left_neighbor_block_has_coefficients(plane)** )
    ctx3++;
if ( **above_neighbor_block_has_coefficients(plane)** )
    ctx3++;

for( i = firstCoeff; i < 16; ++i )
{
    ctx2 = coeff_bands[i];
    probTable = coeff_probs[plane][ctx2][ctx3];

    /* 前のトークンが DCT_0 であれば最初のコード (dct_eob) を飛ばす */
    if ( prevCoeffWasZero )
        token = treed_read ( d, **coeff_tree_without_eob**,
          probTable );
    else
        token = treed_read ( d, coeff_tree, probTable );
    if ( token == dct_eob )
        break;

    if ( token != DCT_0 )
    {
        currentBlockHasCoeffs = true;
  if ( **token_has_extra_bits(token)** )
  {
      extraBits = DCTextra( token );
      absValue =
          categoryBase[**token_to_cat_index(token)**] +
    extraBits;
  }
  else
  {
      absValue = **token_to_abs_value(token)**;
  }

  sign = read_bool(d, 128);
        block[i] = sign ? -absValue : absValue;
    }
    else
    {
        absValue = 0;
    }

    /* 次の係数のためにコンテキストなどを設定 */
    if ( absValue == 0 )         ctx3 = 0;
    else if ( absValue == 1 )   ctx3 = 1;
    else                        ctx3 = 2;
    prevCoeffWasZero = true;
}

/* 現在のブロックの状態をデコーダー内部に保存 */
**block_has_coefficients[currentMb][currentBlock]** =
  currentBlockHasCoeffs;

int i = 0;  do {
 int j = 0;  do {
  int k = 0;  do {
   int t = 0;  do {

        if (read_bool(d, coeff_update_probs [i] [j] [k] [t]))
            coeff_probs [i] [j] [k] [t] = read_literal(d, 8);

   } while (++t < num_dct_tokens - 1);
  } while (++k < 3);
 } while (++j < 8);
} while (++i < 4);

void vp8_short_inv_walsh4x4_c(short *input, short *output)
{
  int i;
  int a1, b1, c1, d1;
  int a2, b2, c2, d2;
  short *ip = input;
  short *op = output;
  int temp1, temp2;

  for(i=0;i<4;i++)
  {
    a1 = ip[0] + ip[12];
    b1 = ip[4] + ip[8];
    c1 = ip[4] - ip[8];
    d1 = ip[0] - ip[12];

    op[0] = a1 + b1;
    op[4] = c1 + d1;
    op[8] = a1 - b1;
    op[12]= d1 - c1;
    ip++;
    op++;
  }
  ip = output;
  op = output;
  for(i=0;i<4;i++)
  {
    a1 = ip[0] + ip[3];
    b1 = ip[1] + ip[2];
    c1 = ip[1] - ip[2];
    d1 = ip[0] - ip[3];

    a2 = a1 + b1;
    b2 = c1 + d1;
    c2 = a1 - b1;
    d2 = d1 - c1;
    op[0] = (a2+3)>>3;
    op[1] = (b2+3)>>3;
    op[2] = (c2+3)>>3;
    op[3] = (d2+3)>>3;

    ip+=4;
    op+=4;
  }
}

void vp8_short_inv_walsh4x4_1_c(short *input, short *output)
{
  int i;
  int a1;
  short *op=output;

  a1 = ((input[0] + 3)>>3);

  for(i=0;i<4;i++)
  {
    op[0] = a1;
    op[1] = a1;
    op[2] = a1;
    op[3] = a1;
    op+=4;
  }
}

/* IDCTの実装 */
static const int cospi8sqrt2minus1=20091;
static const int sinpi8sqrt2      =35468;
void short_idct4x4llm_c(short *input, short *output, int pitch)
{
  int i;
  int a1, b1, c1, d1;

  short *ip=input;
  short *op=output;
  int temp1, temp2;
  int shortpitch = pitch>>1;

  for(i=0;i<4;i++)
  {
    a1 = ip[0]+ip[8];
    b1 = ip[0]-ip[8];

    temp1 = (ip[4] * sinpi8sqrt2)>>16;
    temp2 = ip[12]+((ip[12] * cospi8sqrt2minus1)>>16);
    c1 = temp1 - temp2;

    temp1 = ip[4] + ((ip[4] * cospi8sqrt2minus1)>>16);
    temp2 = (ip[12] * sinpi8sqrt2)>>16;
    d1 = temp1 + temp2;

    op[shortpitch*0] = a1+d1;
    op[shortpitch*3] = a1-d1;
    op[shortpitch*1] = b1+c1;
    op[shortpitch*2] = b1-c1;

    ip++;
    op++;
  }
  ip = output;
  op = output;
  for(i=0;i<4;i++)
  {
    a1 = ip[0]+ip[2];
    b1 = ip[0]-ip[2];

    temp1 = (ip[1] * sinpi8sqrt2)>>16;
    temp2 = ip[3]+((ip[3] * cospi8sqrt2minus1)>>16);
    c1 = temp1 - temp2;

    temp1 = ip[1] + ((ip[1] * cospi8sqrt2minus1)>>16);
    temp2 = (ip[3] * sinpi8sqrt2)>>16;
    d1 = temp1 + temp2;

    op[0] = (a1+d1+4)>>3;
    op[3] = (a1-d1+4)>>3;
    op[1] = (b1+c1+4)>>3;
    op[2] = (b1-c1+4)>>3;

    ip+=shortpitch;
    op+=shortpitch;
  }
}

/* ピクセル値（0 <= v <= 255）を8ビット符号付きの数に
   変換します。 */
int8 u2s(Pixel v) { return (int8) (v - 128);}

/* クランプしてから、符号付きの数をピクセル値に戻します。 */
Pixel s2u(int v) { return (Pixel) (c(v) + 128);}

int8 common_adjust(
    int use_outer_taps,   /* フィルターの幅は2タップまたは4タップ */
    const Pixel *P1,    /* P0の前のピクセル */
    Pixel *P0,          /* エッジの前のピクセル */
    Pixel *Q0,          /* エッジの後のピクセル */
    const Pixel *Q1     /* Q0の後のピクセル */
) {
    cint8 p1 = u2s(*P1);   /* 4つのピクセルをすべて取得して変換 */
    cint8 p0 = u2s(*P0);
    cint8 q0 = u2s(*Q0);
    cint8 q1 = u2s(*Q1);

    /* クランプを無視すると、"use_outer_taps"が偽のとき、"a"は
       3*(q0-p0)です。このあと"a"を8で割るので、この場合はエッジの差に
       5/8を掛けることになります。

       "use_outer_taps"が真のとき（シンプルフィルターの場合）、"a"は
       p1 - 3*p0 + 3*q0 - q1です。これは2*(q0 - p0)を精密化したものと
       考えることができ、調整量はおよそ(q0 - p0)/4になります。 */

    int8 a = c((use_outer_taps? c(p1 - q1) : 0) + 3*(q0 - p0));

    /* bは、a/8の「小数」部分"f"がちょうど1/2の場合に、a/8の丸めの
       釣り合いを取るために使います。 */

    cint8 b = (c(a + 3)) >> 3;

    /* aを8で割り、f >= 1/2のときは切り上げます。
       厳密にはC言語の一部ではありませんが、右シフトは符号ビットを
       伝播するものとします。 */

    a = c(a + 4) >> 3;

    /* q0から"a"を引き、p0に「近づけ」ます。 */

    *Q0 = s2u(q0 - a);
    /* p0に"a"を（調整"b"とともに）加え、q0に「近づけ」ます。

       "a+b"のクランプはリファレンスデコーダーにはありますが、
       不要です。この時点で-16 <= a <= 15だからです。 */

    *P0 = s2u(p0 + b);

    return a;
}

void simple_segment(
    uint8 edge_limit,   /* エッジの差が上限を超えたら
                           何もしない */
    const Pixel *P1,    /* P0の前のピクセル */
    Pixel *P0,          /* エッジの前のピクセル */
    Pixel *Q0,          /* エッジの後のピクセル */
    const Pixel *Q1     /* Q0の後のピクセル */
) {
    if ((abs(*P0 - *Q0)*2 + abs(*P1 - *Q1)/2) <= edge_limit))
        common_adjust(1, P1, P0, Q0, Q1);   /* 外側のタップを使う */
}

/* すべての関数は（ほかの引数とともに）エッジを対称にまたぐ （長さが最大4 + 4 = 8の）セグメントを受け取ります。
ピクセル値（またはポインター）は、常に「最も前」から「最も後」へ 順に与えられます。したがって、水平エッジ（"|"と書きます）では、 8ピクセルのセグメントはp3 p2 p1 p0 | q0 q1 q2 q3の順になります。 */
/* 8ピクセルのセグメント内で隣接する任意の2つの「内部」ピクセルの 差が該当するしきい値（I）を超える場合、フィルター処理は無効に なります。エッジをまたぐ4つのピクセルのグループについては、上の simple_segment()の計算に沿って、より複雑なしきい値計算を 行います。 */ int filter_yes( uint8 I, /* 内部の差の上限 */ uint8 E, /* エッジでの上限 */
cint8 p3, cint8 p2, cint8 p1, cint8 p0, /* エッジの前の ピクセル */ cint8 q0, cint8 q1, cint8 q2, cint8 q3 /* エッジの後の ピクセル */ ) { return (abs(p0 - q0)*2 + abs(p1 - q1)/2) <= E && abs(p3 - p2) <= I && abs(p2 - p1) <= I && abs(p1 - p0) <= I && abs(q3 - q2) <= I && abs(q2 - q1) <= I && abs(q1 - q0) <= I; }

/* エッジのどちらか一方の側の差の（少なくとも）1つがしきい値を
   超える場合（「エッジの分散が大きい」場合）、フィルター処理を
   変更します。 */

int hev(
    uint8 threshold,
    cint8 p1, cint8 p0, /* エッジの前のピクセル */
    cint8 q0, cint8 q1  /* エッジの後のピクセル */
) {
    return abs(p1 - p0) > threshold  ||  abs(q1 - q0) > threshold;
}

void subblock_filter(
    uint8 hev_threshold,     /* エッジの分散が大きいことを検出 */
    uint8 interior_limit,    /* フィルターを無効にすることがある */
    uint8 edge_limit,
    cint8 *P3, cint8 *P2, int8 *P1, int8 *P0,   /* エッジの前の
                                                   ピクセル */
    int8 *Q0, int8 *Q1, cint8 *Q2, cint8 *Q3    /* エッジの後の
                                                   ピクセル */
) {
    cint8 p3 = u2s(*P3), p2 = u2s(*P2), p1 = u2s(*P1),
      p0 = u2s(*P0);
    cint8 q0 = u2s(*Q0), q1 = u2s(*Q1), q2 = u2s(*Q2),
      q3 = u2s(*Q3);

    if (filter_yes(interior_limit, edge_limit, q3, q2, q1, q0,
      p0, p1, p2, p3))
    {
        const int hv = hev(hev_threshold, p1, p0, q0, q1);

        cint8 a = (common_adjust(hv, P1, P0, Q0, Q1) + 1) >> 1;

        if (!hv) {
            *Q1 = s2u(q1 - a);
            *P1 = s2u(p1 + a);
        }
    }
}

void MBfilter(
    uint8 hev_threshold,     /* エッジの分散が大きいことを検出 */
    uint8 interior_limit,    /* フィルターを無効にすることがある */
    uint8 edge_limit,
    cint8 *P3, int8 *P2, int8 *P1, int8 *P0,  /* エッジの前の
                                                 ピクセル */
    int8 *Q0, int8 *Q1, int8 *Q2, cint8 *Q3   /* エッジの後の
                                                 ピクセル */
) {
    cint8 p3 = u2s(*P3), p2 = u2s(*P2), p1 = u2s(*P1),
      p0 = u2s(*P0);
    cint8 q0 = u2s(*Q0), q1 = u2s(*Q1), q2 = u2s(*Q2),
      q3 = u2s(*Q3);

    if (filter_yes(interior_limit, edge_limit, q3, q2, q1, q0,
      p0, p1, p2, p3))
    {
        if (!hev(hev_threshold, p1, p0, q0, q1))
        {
            /* "common_adjust"の最初の計算と同じです。wはエッジの差の
               2倍程度です */

            const int8 w = c(c(p1 - q1) + 3*(q0 - p0));

            /* 9/64はおよそ9/63 = 1/7であり、1<<7 = 128 = 2*64です。
               したがって、エッジに隣接するピクセルの調整に使うこのaは、
               エッジの差のおよそ3/7です。 */

            int8 a = c((27*w + 63) >> 7);

            *Q0 = s2u(q0 - a);  *P0 = s2u(p0 + a);

            /* 次の2つはエッジの差の2/7だけ調整 */

            a = c((18*w + 63) >> 7);

            *Q1 = s2u(q1 - a);  *P1 = s2u(p1 + a);

            /* 最後の2つはエッジの差の1/7だけ調整 */

            a = c((9*w + 63) >> 7);

            *Q2 = s2u(q2 - a);  *P2 = s2u(p2 + a);
        } else                      /* hevならシンプルフィルター */
            common_adjust(1, P1, P0, Q0, Q1);   /* 外側のタップを
                                                    使う */
    }
}

/* 輝度と色差は同じマクロブロック間エッジの上限を使う */
uint8 mbedge_limit = ((loop_filter_level + 2) * 2) +
  interior_limit;

/* 輝度と色差は同じサブブロック間エッジの上限を使う */
uint8 sub_bedge_limit = (loop_filter_level * 2) + interior_limit;

uint8 interior_limit = loop_filter_level;

if (sharpness_level)
{
    interior_limit  >>=  sharpness_level > 4 ?  2 : 1;
    if (interior_limit > 9 - sharpness_level)
        interior_limit = 9 - sharpness_level;
}
if (!interior_limit)
    interior_limit = 1;

uint8 hev_threshold = 0;

if (we_are_decoding_akey_frame)   /* 現在のフレームはキーフレーム */
{
    if (loop_filter_level >= 40)
        hev_threshold = 2;
    else if (loop_filter_level >= 15)
        hev_threshold = 1;
}
else                            /* 現在のフレームはインターフレーム */
{
    if (loop_filter_level >= 40)
        hev_threshold = 3;
    else if (loop_filter_level >= 20)
        hev_threshold = 2;
    else if (loop_filter_level >= 15)
        hev_threshold = 1;
}

