{
 -DC_PRED, 2,           /* ルート: DC_PRED = "0"、"1" サブツリー */
  4, 6,                 /* "1" サブツリーは 2 つの子孫サブツリーを持つ */
   -V_PRED, -H_PRED,    /* "10" サブツリー:  V_PRED = "100"、
                           H_PRED = "101" */
   -TM_PRED, -B_PRED    /* "11" サブツリー:  TM_PRED = "110"、
                           B_PRED = "111" */
};

const Prob bmode_prob [num_intra_bmodes - 1] = {
    120, 90, 79, 133, 87, 85, 80, 111, 151
};

typedef enum
{
    mv_nearest = num_ymodes, /* MB 全体に「最も近い」動き
                                ベクトルを使う */
    mv_near,                 /* 「次に近い」"" を使う */
    mv_zero,                 /* ゼロの "" を使う */
    mv_new,                  /* 暗黙の "" からの明示的な
                                オフセットを使う */
    mv_split,                /* 複数の動きベクトルを使う */

    num_mv_refs = mv_split + 1 - mv_nearest
}
mv_ref;

const tree_index mv_ref_tree [2 * (num_mv_refs - 1)] =
{
 -mv_zero, 2,                /* zero = "0" */
  -mv_nearest, 4,            /* nearest = "10" */
   -mv_near, 6,              /* near = "110" */
     -mv_new, -mv_split      /* new = "1110"、split = "1111" */
};

typedef union
{
    unsigned int as_int;
    MV           as_mv;
} int_mv;        /* 等価性の判定を高速にする */


static void mv_bias(MODE_INFO *x,int refframe, int_mv *mvp,
  int * ref_frame_sign_bias)
{
    MV xmv;
    xmv = x->mbmi.mv.as_mv;
    if ( ref_frame_sign_bias[x->mbmi.ref_frame] !=
      ref_frame_sign_bias[refframe] )
    {
        xmv.row*=-1;
        xmv.col*=-1;
    }
    mvp->as_mv = xmv;
}

void vp8_clamp_mv(MV *mv, const MACROBLOCKD *xd)
{
    if ( mv->col < (xd->mb_to_left_edge - LEFT_TOP_MARGIN) )
        mv->col = xd->mb_to_left_edge - LEFT_TOP_MARGIN;
    else if ( mv->col > xd->mb_to_right_edge + RIGHT_BOTTOM_MARGIN )
        mv->col = xd->mb_to_right_edge + RIGHT_BOTTOM_MARGIN;

    if ( mv->row < (xd->mb_to_top_edge - LEFT_TOP_MARGIN) )
        mv->row = xd->mb_to_top_edge - LEFT_TOP_MARGIN;
    else if ( mv->row > xd->mb_to_bottom_edge + RIGHT_BOTTOM_MARGIN )
        mv->row = xd->mb_to_bottom_edge + RIGHT_BOTTOM_MARGIN;
}

void vp8_find_near_mvs
(
    MACROBLOCKD *xd,
    const MODE_INFO *here,
    MV *nearest,
    MV *near,
    MV *best_mv,
    int cnt[4],
    int refframe,
    int * ref_frame_sign_bias
)
{
    const MODE_INFO *above = here - xd->mode_info_stride;
    const MODE_INFO *left = here - 1;
    const MODE_INFO *aboveleft = above - 1;
    int_mv            near_mvs[4];
    int_mv           *mv = near_mvs;
    int             *cntx = cnt;
    enum {CNT_ZERO, CNT_NEAREST, CNT_NEAR, CNT_SPLITMV};

    /* 累積値をゼロにする */
    mv[0].as_int = mv[1].as_int = mv[2].as_int = 0;
    cnt[0] = cnt[1] = cnt[2] = cnt[3] = 0;

    /* 上を処理する */
    if (above->mbmi.ref_frame != INTRA_FRAME) {
        if (above->mbmi.mv.as_int) {
            (++mv)->as_int = above->mbmi.mv.as_int;
            mv_bias(above, refframe, mv, ref_frame_sign_bias);
            ++cntx;
        }
        *cntx += 2;
    }

    /* 左を処理する */
    if (left->mbmi.ref_frame != INTRA_FRAME) {
        if (left->mbmi.mv.as_int) {
            int_mv this_mv;

            this_mv.as_int = left->mbmi.mv.as_int;
            mv_bias(left, refframe, &this_mv, ref_frame_sign_bias);

            if (this_mv.as_int != mv->as_int) {
                (++mv)->as_int = this_mv.as_int;
                ++cntx;
            }
            *cntx += 2;
        } else
            cnt[CNT_ZERO] += 2;
    }

    /* 左上を処理する */
    if (aboveleft->mbmi.ref_frame != INTRA_FRAME) {
        if (aboveleft->mbmi.mv.as_int) {
            int_mv this_mv;

            this_mv.as_int = aboveleft->mbmi.mv.as_int;
            mv_bias(aboveleft, refframe, &this_mv,
              ref_frame_sign_bias);
            if (this_mv.as_int != mv->as_int) {
                (++mv)->as_int = this_mv.as_int;
                ++cntx;
            }
            *cntx += 1;
        } else
            cnt[CNT_ZERO] += 1;
    }

    /* 相異なる MV が 3 つある場合 ... */
    if (cnt[CNT_SPLITMV]) {
        /* 左上の MV を NEAREST とまとめられるか確認する */
        if (mv->as_int == near_mvs[CNT_NEAREST].as_int)
            cnt[CNT_NEAREST] += 1;
    }

    cnt[CNT_SPLITMV] = ((above->mbmi.mode == SPLITMV)
                         + (left->mbmi.mode == SPLITMV)) * 2
                        + (aboveleft->mbmi.mode == SPLITMV);

    /* 必要なら near と nearest を入れ替える */
    if (cnt[CNT_NEAR] > cnt[CNT_NEAREST]) {
        int tmp;
        tmp = cnt[CNT_NEAREST];
        cnt[CNT_NEAREST] = cnt[CNT_NEAR];
        cnt[CNT_NEAR] = tmp;
        tmp = near_mvs[CNT_NEAREST].as_int;
        near_mvs[CNT_NEAREST].as_int = near_mvs[CNT_NEAR].as_int;
        near_mvs[CNT_NEAR].as_int = tmp;
    }

    /* near_mvs[0] を使って「best」MV を格納する */
    if (cnt[CNT_NEAREST] >= cnt[CNT_ZERO])
        near_mvs[CNT_ZERO] = near_mvs[CNT_NEAREST];

    /* 戻り値を設定する */
    *best_mv = near_mvs[0].as_mv;
    *nearest = near_mvs[CNT_NEAREST].as_mv;
    *near = near_mvs[CNT_NEAR].as_mv;

    vp8_clamp_mv(nearest, xd);
    vp8_clamp_mv(near, xd);
    vp8_clamp_mv(best_mv, xd); //TODO: Move this up before
                                 the copy
}

vp8_prob *vp8_mv_ref_probs(vp8_prob mv_ref_p[VP8_MVREFS-1],
  int cnt[4])
{
    mv_ref_p[0] = vp8_mode_contexts [cnt[0]] [0];
    mv_ref_p[1] = vp8_mode_contexts [cnt[1]] [1];
    mv_ref_p[2] = vp8_mode_contexts [cnt[2]] [2];
    mv_ref_p[3] = vp8_mode_contexts [cnt[3]] [3];
    return p;
}

