/* 正しいデコードツリーのコンテキストを選択する
 * 関数のパラメーターは、左の隣接サブブロックの MV と上の隣接
 * サブブロックの MV */
int vp8_mvCont(MV *l, MV*a)
{
    int lez = (l->row == 0 && l->col == 0);   /* 左の隣接が
                                                 ゼロ */
    int aez = (a->row == 0 && a->col == 0);   /* 上の隣接が
                                                 ゼロ */
    int lea = (l->row == a->row && l->col == a->col);  /* 左の
                             隣接が上の隣接と等しい */

    if (lea && lez)
        return SUBMVREF_LEFT_ABOVE_ZED; /* =4 */

    if (lea)
        return SUBMVREF_LEFT_ABOVE_SAME; /* =3 */

    if (aez)
        return SUBMVREF_ABOVE_ZED; /* =2 */

    if (lez)
        return SUBMVREF_LEFT_ZED; /* =1*/

    return SUBMVREF_NORMAL; /* =0 */
}

