typedef enum
{
    mvpis_short,         /* short (<= 7) か long (>= 8) か */
    MVPsign,             /* 非ゼロの場合の符号 */
    MVPshort,            /* 8 つの short の値 = 7 要素のツリー */

    MVPbits = MVPshort + 7,      /* long の値の 8 ビット、
                                    それぞれ独立の確率 */

    MVPcount = MVPbits + 10      /* 合計 19 個の確率 */
}
MVPindices;

typedef Prob MV_CONTEXT [MVPcount];    /* 1 つの成分の
                                          デコード仕様 */

/* 小さな絶対値に使うツリー（予想どおりの対応関係を
   持つ）。 */

const tree_index small_mvtree [2 * (8 - 1)] =
{
 2, 8,          /* "0" サブツリー、"1" サブツリー */
  4, 6,         /* "00" サブツリー、"01" サブツリー */
   -0, -1,      /* 0 = "000", 1 = "001" */
   -2, -3,      /* 2 = "010", 3 = "011" */
  10, 12,       /* "10" サブツリー、"11" サブツリー */
   -4, -5,      /* 4 = "100", 5 = "101" */
   -6, -7       /* 6 = "110", 7 = "111" */
};

/* 与えられた確率を使って、現在のデコーダー位置から MV の
   成分を読み取る。 */

int read_mvcomponent(bool_decoder *d, const MV_CONTEXT *mvc)
{
    const Prob * const p = (const Prob *) mvc;
    int A = 0;

    if (read_bool(d, p [mvpis_short]))    /* 8 <= A <= 1023 */
    {
        /* ビット 0、1、2 を読み取る */

        int i = 0;
        do { A += read_bool(d, p [MVPbits + i]) << i;}
          while (++i < 3);

        /* ビット 9、8、7、6、5、4 を読み取る */

        i = 9;
        do { A += read_bool(d, p [MVPbits + i]) << i;}
          while (--i > 3);

        /* long として符号化されているので A >= 8 であることが
           わかっています。したがって A <= 15 であれば、ビット 3
           は 1 であり、明示的には符号化されません。 */

        if (!(A & 0xfff0)  ||  read_bool(d, p [MVPbits + 3]))
            A += 8;
    }
    else    /* 0 <= A <= 7 */
        A = treed_read(d, small_mvtree, p + MVPshort);

    return A && read_bool(r, p [MVPsign]) ?  -A : A;
}

