/* 現在の MV のデコードの確率。キーフレームごとに上記の
   デフォルト値に設定されます。 */

MV_CONTEXT mvc [2];     /* 常に行、次に列 */
/* 完全な動きベクトルをデコードする手順。 */

typedef struct { int16 row, col;}  MV;  /* 前のセクションと同じ */

MV read_mv(bool_decoder *d)
{
    MV v;
    v.row = (int16) read_mvcomponent(d, mvc);
    v.col = (int16) read_mvcomponent(d, mvc + 1);
    return v;
}

/* MV のデコードの確率を更新する手順。インターフレームごとに、
   "d" をフレームヘッダー内の適切な位置に置いた状態で呼び出し
   ます。 */

void update_mvcontexts(bool_decoder *d)
{
    int i = 0;
    do {                      /* 成分 = 行、次に列 */
        const Prob *up = mv_update_probs[i];    /* 成分の
                                                   更新確率 */
        Prob *p = mvc[i];                  /* デコード表の先頭 "" */
        Prob * const pstop = p + MVPcount; /* デコード表の末尾 "" */
        do {
            if (read_bool(d, *up++))     /* この位置を更新 */
            {
                const Prob x = read_literal(d, 7);

                *p = x? x<<1 : 1;
            }
        } while (++p < pstop);              /* 次の位置 */
    } while (++i < 2);                      /* 次の成分 */
}

int avg(int c1, int c2, int c3, int c4)
{
    int s = c1 + c2 + c3 + c4;

    /* 色差のピクセルは輝度のピクセルの2倍の直径を持つため、
       シフトでは（4ではなく）8で割ります。厳密に言えば、C
       では負の数の右シフトが明確に定義されていないため、負の
       動きベクトル成分の扱いは少し面倒です。 */

    return s >= 0 ?  (s + 4) >> 3 : -((-s + 4) >> 3);
}

/* フィルタータップは7ビット精度です。
   DC は常に通過させるため、タップの合計は常に128になります。 */

const int BilinearFilters[8][6] =
{
    { 0, 0, 128,   0, 0, 0 },
    { 0, 0, 112,  16, 0, 0 },
    { 0, 0,  96,  32, 0, 0 },
    { 0, 0,  80,  48, 0, 0 },
    { 0, 0,  64,  64, 0, 0 },
    { 0, 0,  48,  80, 0, 0 },
    { 0, 0,  32,  96, 0, 0 },
    { 0, 0,  16, 112, 0, 0 }
};

const int filters [8] [6] = {        /* 変位でインデックス付け */
    { 0,  0,  128,    0,   0,  0 },  /* 縮退した整数ピクセル */
    { 0, -6,  123,   12,  -1,  0 },  /* 1/8 */
    { 2, -11, 108,   36,  -8,  1 },  /* 1/4 */
    { 0, -9,   93,   50,  -6,  0 },  /* 3/8 */
    { 3, -16,  77,   77, -16,  3 },  /* 1/2 は対称 */
    { 0, -6,   50,   93,  -9,  0 },  /* 5/8 = 3/8 の逆順 */
    { 1, -8,   36,  108, -11,  2 },  /* 3/4 = 1/4 の逆順 */
    { 0, -1,   12,  123,  -6,  0 }   /* 7/8 = 1/8 の逆順 */
};
/* 1つのサンプルの1次元合成。
   フィルターは小数の変位によって決まります */

Pixel interp(
    const int fil[6],   /* 適用するフィルター */
    const Pixel *p,     /* 予測領域内の（「前」に丸めた）
                           原点 */
    const int s         /* 1回の前方ステップの大きさ（同上） */
) {
    int32 a = 0;
    int i = 0;
    p -= s + s;         /* 2つ前の位置に戻す */

    do {
        a += *p * fil[i];
        p += s;
    }  while (++i < 6);

    return clamp255((a + 64) >> 7);    /* 最も近い8ビット値に
                                           丸める */
}


/* まず水平方向の補間を行い、中間バッファーを生成します。 */

void Hinterp(
    Pixel temp[9][4],   /* 4個×9行の（中間の）出力先の
                           値 */
    const Pixel *p,     /* 予測フレーム内のサブブロックの
                           原点 */
    int s,              /* 予測フレームで使う垂直方向の
                           ストライド */
    uint hfrac,         /* 0 <= 水平方向の変位 <= 7 */
    uint bicubic        /* 1=バイキュービックフィルター、0=バイリニア */
) {
    const int * const fil = bicubic ? filters [hfrac] :
      BilinearFilters[hfrac];

    int r = 0;  do              /* 各行について */
    {
        int c = 0;  do          /* 出力先の各サンプルについて */
        {
            /* ピクセル間隔 = 水平方向の1ステップ = 1 */

            temp[r][c] = interp(fil, p + c, 1);
        }
        while (++c < 4);
    }
    while (p += s, ++r < 9);    /* p を次の行に進める */
}

/* 最後に垂直方向の補間を行い、最終的な結果を生成します。
   入力配列 "temp" は、もちろん上で計算したものです。 */

void Vinterp(
    Pixel final[4][4],  /* 4個×4行の（最終的な）出力先の値 */
    const Pixel temp[9][4],
    uint vfrac,         /* 0 <= 垂直方向の変位 <= 7 */
    uint bicubic        /* 1=バイキュービックフィルター、0=バイリニア */
) {
    const int * const fil = bicubic ? filters [vfrac] :
      BilinearFilters[vfrac];

    int r = 0;  do              /* 各行について */
    {
        int c = 0;  do          /* 出力先の各サンプルについて */
        {
            /* ピクセル間隔 = 垂直方向の1ステップ = 配列の幅 = 4 */

            final[r][c] = interp(fil, temp[r] + c, 4);
        }
        while (++c < 4);
    }
    while (++r < 4);
}

unsigned char *c = pbi->source;
