#ifndef BOOL_DECODER_H
#define BOOL_DECODER_H
#include <stddef.h>
struct bool_decoder
{
    const unsigned char *input;      /* 次の圧縮データのバイト */
    size_t               input_len;  /* 入力バッファーの長さ */
    unsigned int         range;      /* エンコーダーの range と同一 */
    unsigned int         value;      /* 有効ビットを 8 ビット以上
                                      * 保持 */
    int                  bit_count;  /* value からシフトアウトした
                                      * ビット数、最大 7 */
};

static void
init_bool_decoder(struct bool_decoder *d,
                  const unsigned char *start_partition,
                  size_t               sz)
{
    if (sz >= 2)
    {
        d->value = (start_partition[0] << 8) /* 入力の最初の
                                              * 2 バイト */
                   | start_partition[1];
        d->input = start_partition + 2;      /* 次のバイトへの
                                              * ポインター */
        d->input_len = sz - 2;
    }
    else
    {
        d->value = 0;
        d->input = NULL;
        d->input_len = 0;
    }

    d->range = 255;    /* 初期の range は最大 */
    d->bit_count = 0;  /* まだどのビットもシフトアウトしていません */
}

static int bool_get(struct bool_decoder *d, int probability)
{
    /* range と split は、このブール値を書き込んだときに
       エンコーダーが使った対応する値と同一です */

    unsigned int  split = 1 + (((d->range - 1) * probability) >> 8);
    unsigned int  SPLIT = split << 8;
    int           retval;           /* 0 または 1 */
    if (d->value >= SPLIT)    /* 1 が符号化されている場合 */
    {
        retval = 1;
        d->range -= split;  /* range を縮小 */
        d->value -= SPLIT;  /* 区間の左端を減算 */
    }
    else                  /* 0 が符号化されている場合 */
    {
        retval = 0;
        d->range = split; /* range を縮小、左端は変化なし */
    }

    while (d->range < 128)    /* value の不要なビットをシフトアウト */
    {
        d->value <<= 1;
        d->range <<= 1;

        if (++d->bit_count == 8)  /* 新しいビットを 8 ビットずつ
                                   * シフトイン */
        {
            d->bit_count = 0;

            if (d->input_len)
            {
                d->value |= *d->input++;
                d->input_len--;
            }
        }
    }

    return retval;
}

static int bool_get_bit(struct bool_decoder *br)
{
    return bool_get(br, 128);
}
static int bool_get_uint(struct bool_decoder *br, int bits)
{
    int z = 0;
    int bit;

    for (bit = bits - 1; bit >= 0; bit--)
    {
        z |= (bool_get_bit(br) << bit);
    }

    return z;
}

static int bool_get_int(struct bool_decoder *br, int bits)
{
    int z = 0;
    int bit;

    for (bit = bits - 1; bit >= 0; bit--)
    {
        z |= (bool_get_bit(br) << bit);
    }

    return bool_get_bit(br) ? -z : z;
}

static int bool_maybe_get_int(struct bool_decoder *br, int bits)
{
    return bool_get_bit(br) ? bool_get_int(br, bits) : 0;
}

static int
bool_read_tree(struct bool_decoder *bool,
               const int           *t,
               const unsigned char *p)
{
    int i = 0;

    while ((i = t[ i + bool_get(bool, p[i>>1])]) > 0);

    return -i;
}
