/*!\file vpx_codec_internal.h
 * \brief アルゴリズムの実装向けに、デコーダーアルゴリズムの
 *        インターフェースを記述します。
 *
 * このファイルは、アルゴリズムを使用する場合ではなく、アルゴリズムを
 * 実装する場合にのみ関係する非公開の構造体とデータ型を定義します。
 *
 * デコーダーアルゴリズムのクラスを作成するには、インターフェース
 * 構造体をグローバル名前空間に置きます:
 *     <pre>
 *     my_codec.c:
 *       vpx_codec_iface_t my_codec = {
 *           "My Codec v1.0",
 *           VPX_CODEC_ALG_ABI_VERSION,
 *           ...
 *       };
 *     </pre>
 *
 * アプリケーションは、vpx_codec_init() とアルゴリズムの
 * インターフェース構造体へのポインターを使用して、特定のデコーダー
 * インスタンスを生成します:
 *     <pre>
 *     my_app.c:
 *       extern vpx_codec_iface_t my_codec;
 *       {
 *           vpx_codec_ctx_t algo;
 *           res = vpx_codec_init(&algo, &my_codec);
 *       }
 *     </pre>
 *
 * 初期化したあとは、vpx_codec_* 系のほかの関数を使用して
 * インスタンスを管理します。
 */
#ifndef VPX_CODEC_INTERNAL_H
#define VPX_CODEC_INTERNAL_H
#include "vpx_decoder.h"
#include <stdarg.h>


/*!\brief 現在の ABI バージョン番号
 *
 * \internal
 * アプリケーションバイナリーインターフェース（ABI）が変わるような
 * 変更をこのファイルに加えた場合は、この値を増やさなければ
 * なりません。たとえば、型の変更、列挙値の削除や再割り当て、構造体の
 * フィールドの追加・削除・並べ替えなどがありますが、これらに限り
 * ません。
 */
#define VPX_CODEC_INTERNAL_ABI_VERSION (3)

typedef struct vpx_codec_alg_priv  vpx_codec_alg_priv_t;

/*!\brief init 関数ポインターのプロトタイプ
 *
 * デコーダーコンテキストのアルゴリズム固有の初期化を行います。
 * この関数は汎用のラッパー関数 vpx_codec_init() から呼び出されるので、
 * このインターフェースを実装するプラグインは、入力パラメーターが
 * 適切に初期化されていると信頼してかまいません。
 *
 * \param[in] ctx   このインスタンスのコンテキストへのポインター
 * \retval #VPX_CODEC_OK
 *     入力ストリームを認識し、デコーダーを初期化しました。
 * \retval #VPX_CODEC_MEM_ERROR
 *     メモリー操作に失敗しました。
 */
typedef vpx_codec_err_t (*vpx_codec_init_fn_t)(vpx_codec_ctx_t *ctx);
/*!\brief destroy 関数ポインターのプロトタイプ
 *
 * デコーダーコンテキストのアルゴリズム固有の破棄を行います。
 * この関数は汎用のラッパー関数 vpx_codec_destroy() から呼び出される
 * ので、このインターフェースを実装するプラグインは、入力パラメーターが
 * 適切に初期化されていると信頼してかまいません。
 *
 * \param[in] ctx   このインスタンスのコンテキストへのポインター
 * \retval #VPX_CODEC_OK
 *     入力ストリームを認識し、デコーダーを初期化しました。
 * \retval #VPX_CODEC_MEM_ERROR
 *     メモリー操作に失敗しました。
 */
typedef vpx_codec_err_t (*vpx_codec_destroy_fn_t)(
    vpx_codec_alg_priv_t *ctx);

/*!\brief ストリーム情報解析関数ポインターのプロトタイプ
 *
 * ビットストリームの高レベルの解析を行います。この関数は汎用の
 * ラッパー関数 vpx_codec_parse_stream() から呼び出されるので、この
 * インターフェースを実装するプラグインは、入力パラメーターが適切に
 * 初期化されていると信頼してかまいません。
 *
 * \param[in]      data    解析するデータブロックへのポインター
 * \param[in]      data_sz データバッファーのサイズ
 * \param[in,out]  si      更新するストリーム情報へのポインター。
 *                         size メンバーは適切に初期化されて
 *                         いなければなりません（\ref MUST）が、
 *                         アルゴリズムが上書きしてもよいです
 *                         （\ref MAY）。このパラメーターは NULL
 *                         でもよいです（\ref MAY）。
 *
 * \retval #VPX_CODEC_OK
 *     ビットストリームが解析可能で、ストリーム情報を更新しました
 */
typedef vpx_codec_err_t (*vpx_codec_peek_si_fn_t)(
    const uint8_t         *data,
    unsigned int           data_sz,
    vpx_codec_stream_info_t *si);
/*!\brief 現在のストリームに関する情報を返します。
 *
 * デコード中に解析されたストリームに関する情報を返します。
 *
 * \param[in]      ctx     このインスタンスのコンテキストへのポインター
 * \param[in,out]  si      更新するストリーム情報へのポインター。
 *                         size メンバーは適切に初期化されて
 *                         いなければなりません（\ref MUST）が、
 *                         アルゴリズムが上書きしてもよいです
 *                         （\ref MAY）。このパラメーターは NULL
 *                         でもよいです（\ref MAY）。
 *
 * \retval #VPX_CODEC_OK
 *     ビットストリームが解析可能で、ストリーム情報を更新しました
 */
typedef vpx_codec_err_t (*vpx_codec_get_si_fn_t)(
    vpx_codec_alg_priv_t    *ctx,
    vpx_codec_stream_info_t *si);

/*!\brief control 関数ポインターのプロトタイプ
 *
 * この関数は、デコーダーインスタンスとアルゴリズム固有のデータを
 * やり取りするために使用します。特定のアルゴリズムに固有の機能を
 * 実装するために使用できます。
 *
 * この関数は汎用のラッパー関数 vpx_codec_control() から呼び出される
 * ので、このインターフェースを実装するプラグインは、入力パラメーターが
 * 適切に初期化されていると信頼してかまいません。ただし、この
 * インターフェースは、やり取りするデータの型安全性を提供せず、
 * 制御コードに意味を割り当てることもしません。それらの詳細は
 * アルゴリズムのヘッダーファイルで規定すべきです。特に、ctrl_id
 * パラメーターはアルゴリズムの制御マッピングテーブルに存在することが
 * 保証されており、data パラメーターは NULL の場合があります。
 *
 *
 * \param[in]     ctx       このインスタンスのコンテキストへのポインター
 * \param[in]     ctrl_id   アルゴリズム固有の制御識別子
 * \param[in,out] data      アルゴリズムインスタンスとやり取りするデータ。
 *
 * \retval #VPX_CODEC_OK
 *     内部状態データをデシリアライズしました。
 */
typedef vpx_codec_err_t (*vpx_codec_control_fn_t)(
    vpx_codec_alg_priv_t  *ctx,
    int                   ctrl_id,
    va_list               ap);
/*!\brief control 関数ポインターのマッピング
 *
 * この構造体は、制御識別子と、それを実装する関数との対応を格納します。
 * 各アルゴリズムは、この対応のリストを提供します。このリストは、
 * 呼び出す関数を決めるためにラッパー関数 vpx_codec_control() が
 * 検索します。特別な値 {0, NULL} はリストの終わりを示すために使用し、
 * 必ず存在しなければなりません。特別な値 {0, <non-null>} は、
 * すべてを受け付けるマッピングとして使用できます。このことから、
 * アルゴリズムが選ぶ ctrl_id の値は 0 以外でなければなりません
 * （\ref MUST）。
 */
typedef const struct
{
    int                    ctrl_id;
    vpx_codec_control_fn_t   fn;
} vpx_codec_ctrl_fn_map_t;

/*!\brief データデコード関数ポインターのプロトタイプ
 *
 * 符号化データのバッファーを処理します。処理の結果、新しくデコード
 * されたフレームが利用可能になった場合は、必要に応じて
 * #VPX_CODEC_CB_PUT_SLICE イベントと #VPX_CODEC_CB_PUT_FRAME
 * イベントを生成します。この関数は汎用のラッパー関数
 * vpx_codec_decode() から呼び出されるので、このインターフェースを
 * 実装するプラグインは、入力パラメーターが適切に初期化されていると
 * 信頼してかまいません。
 *
 * \param[in] ctx         このインスタンスのコンテキストへのポインター
 * \param[in] data        新しい符号化データのブロックへのポインター。
 *                        NULL の場合は、直前にデコードしたフレームに
 *                        対して #VPX_CODEC_CB_PUT_FRAME イベントを
 *                        送出します。
 * \param[in] data_sz     符号化データのサイズ（バイト単位）。
 *
 * \return 符号化データを完全に処理し、以降のピクチャーをエラーなしで
 *         デコードできる場合は #VPX_CODEC_OK を返します。それ以外の
 *         場合の回復可能性については、::vpx_codec_err_t のほかの
 *         エラーコードの説明を参照してください。
 */
typedef vpx_codec_err_t (*vpx_codec_decode_fn_t)(
    vpx_codec_alg_priv_t  *ctx,
    const uint8_t         *data,
    unsigned int     data_sz,
    void        *user_priv,
    long         deadline);
/*!\brief デコード済みフレームのイテレーター
 *
 * 表示可能なフレームのリストを順にたどります。反復を開始するには、
 * イテレーターの格納領域を NULL に初期化すべきです。この関数が
 * NULL を返すと反復は完了です。
 *
 * 利用可能なフレームのリストは、vpx_codec_decode の呼び出しが完了
 * した時点で有効になり、次に vpx_codec_decode を呼び出すまで有効な
 * ままです。
 *
 * \param[in]     ctx      このインスタンスのコンテキストへのポインター
 * \param[in out] iter     イテレーターの格納領域。NULL に初期化します
 *
 * \return 表示の準備ができた画像があれば、その画像へのポインターを
 *         返します。生成されるフレームは常に PTS（presentation time
 *         stamp）の順になります。
 */
typedef vpx_image_t*(*vpx_codec_get_frame_fn_t)(
    vpx_codec_alg_priv_t *ctx,
    vpx_codec_iter_t     *iter);

/*\brief 外部メモリー割り当てのメモリーマップ取得イテレーター
 *
 * デコーダーが要求するメモリーマップのリストを順にたどります。
 * 反復を開始するには、イテレーターの格納領域を NULL に初期化
 * すべきです。この関数が NULL を返すと反復は完了です。
 *
 * \param[in out] iter     イテレーターの格納領域。NULL に初期化します
 *
 * \return メモリーセグメント記述子へのポインター、またはリストの
 *         終わりを示す NULL を返します。
 */
typedef vpx_codec_err_t (*vpx_codec_get_mmap_fn_t)(
    const vpx_codec_ctx_t      *ctx,
    vpx_codec_mmap_t           *mmap,
    vpx_codec_iter_t           *iter);
/*\brief 外部メモリー割り当てのメモリーマップ設定イテレーター
 *
 * デコーダーインスタンス内にメモリー記述子を設定します。
 *
 * \param[in] ctx      このインスタンスのコンテキストへのポインター
 * \param[in] mmap     格納するメモリーマップ。
 *
 * \retval #VPX_CODEC_OK
 *     メモリーマップを受け入れ、格納しました。
 * \retval #VPX_CODEC_MEM_ERROR
 *     メモリーマップを拒否しました。
 */
typedef vpx_codec_err_t (*vpx_codec_set_mmap_fn_t)(
    vpx_codec_ctx_t         *ctx,
    const vpx_codec_mmap_t  *mmap);


typedef vpx_codec_err_t (*vpx_codec_encode_fn_t)(
    vpx_codec_alg_priv_t  *ctx,
    const vpx_image_t     *img,
    vpx_codec_pts_t        pts,
    unsigned long          duration,
    vpx_enc_frame_flags_t  flags,
    unsigned long          deadline);
typedef const vpx_codec_cx_pkt_t*(*vpx_codec_get_cx_data_fn_t)(
    vpx_codec_alg_priv_t *ctx,
    vpx_codec_iter_t     *iter);

typedef vpx_codec_err_t
(*vpx_codec_enc_config_set_fn_t)(
    vpx_codec_alg_priv_t       *ctx,
    const vpx_codec_enc_cfg_t  *cfg);
typedef vpx_fixed_buf_t *
(*vpx_codec_get_global_headers_fn_t)(vpx_codec_alg_priv_t   *ctx);

typedef vpx_image_t *
(*vpx_codec_get_preview_frame_fn_t)(vpx_codec_alg_priv_t   *ctx);

/*!\brief 用途と設定のマッピング
 *
 * この構造体は、用途の識別子と設定の構造体との対応を格納します。
 * 各アルゴリズムは、この対応のリストを提供します。このリストは、
 * 返す設定を決めるためにラッパー関数 vpx_codec_enc_config_default()
 * が検索します。特別な値 {-1, {0}} はリストの終わりを示すために使用し、
 * 必ず存在しなければなりません。リストの終わりに加えて、少なくとも
 * 1 つのマッピングが存在しなければなりません。
 *
 */
typedef const struct
{
    int                 usage;
    vpx_codec_enc_cfg_t cfg;
} vpx_codec_enc_cfg_map_t;

#define NOT_IMPLEMENTED 0

/*!\brief デコーダーアルゴリズムのインターフェース
 *
 * すべてのデコーダーは、この型の変数を公開しなければなりません
 * （\ref MUST）。
 */
struct vpx_codec_iface
{
    const char               *name;
    int                       abi_version;
    vpx_codec_caps_t          caps;
    vpx_codec_init_fn_t       init;
    vpx_codec_destroy_fn_t    destroy;
    vpx_codec_ctrl_fn_map_t  *ctrl_maps;
    vpx_codec_get_mmap_fn_t   get_mmap;
    vpx_codec_set_mmap_fn_t   set_mmap;
    struct
    {
        vpx_codec_peek_si_fn_t    peek_si;
        vpx_codec_get_si_fn_t     get_si;
        vpx_codec_decode_fn_t     decode;
        vpx_codec_get_frame_fn_t  get_frame;
    } dec;
    struct
    {
        vpx_codec_enc_cfg_map_t           *cfg_maps;
        vpx_codec_encode_fn_t              encode;
        vpx_codec_get_cx_data_fn_t         get_cx_data;
        vpx_codec_enc_config_set_fn_t      cfg_set;
        vpx_codec_get_global_headers_fn_t  get_glob_hdrs;
        vpx_codec_get_preview_frame_fn_t   get_preview;
    } enc;
};
/*!\brief コールバック関数ポインターとユーザーデータの組の格納領域 */
typedef struct vpx_codec_priv_cb_pair
{
    union
    {
        vpx_codec_put_frame_cb_fn_t    put_frame;
        vpx_codec_put_slice_cb_fn_t    put_slice;
    };
    void                            *user_priv;
} vpx_codec_priv_cb_pair_t;


/*!\brief インスタンスの非公開の格納領域
 *
 * この構造体は、アルゴリズムの init 関数が割り当てます。この構造体は
 * 2 つの方法のどちらかで拡張できます。1 つ目は、アルゴリズム固有の
 * 2 つ目の構造体を割り当て、priv メンバーがそれを指すようにする方法
 * です。もう 1 つは、この構造体をアルゴリズム固有の構造体の最初の
 * メンバーにし、ポインターを適切な型にキャストする方法です。
 */
struct vpx_codec_priv
{
    unsigned int                    sz;
    vpx_codec_iface_t              *iface;
    struct vpx_codec_alg_priv      *alg_priv;
    const char                     *err_detail;
    vpx_codec_flags_t               init_flags;
    struct
    {
        vpx_codec_priv_cb_pair_t    put_frame_cb;
        vpx_codec_priv_cb_pair_t    put_slice_cb;
    } dec;
    struct
    {
        struct vpx_fixed_buf        cx_data_dst_buf;
        unsigned int                cx_data_pad_before;
        unsigned int                cx_data_pad_after;
        vpx_codec_cx_pkt_t          cx_data_pkt;
    } enc;
};

#undef VPX_CTRL_USE_TYPE
#define VPX_CTRL_USE_TYPE(id, typ) \
    static typ id##__value(va_list args) \
    {return va_arg(args, typ);} \
    static typ id##__convert(void *x)\
    {\
        union\
        {\
            void *x;\
            typ   d;\
        } u;\
        u.x = x;\
        return u.d;\
    }


#undef VPX_CTRL_USE_TYPE_DEPRECATED
#define VPX_CTRL_USE_TYPE_DEPRECATED(id, typ) \
    static typ id##__value(va_list args) \
    {return va_arg(args, typ);} \
    static typ id##__convert(void *x)\
    {\
        union\
        {\
            void *x;\
            typ   d;\
        } u;\
        u.x = x;\
        return u.d;\
    }

#define CAST(id, arg) id##__value(arg)
#define RECAST(id, x) id##__convert(x)


/* 内部ユーティリティー関数
 *
 * 以下の関数は、vpx_codec_* のデータ構造を操作するユーティリティー
 * として、アルゴリズムの内部で使用することを意図しています。
 */
struct vpx_codec_pkt_list
{
    unsigned int            cnt;
    unsigned int            max;
    struct vpx_codec_cx_pkt pkts[1];
};

#define vpx_codec_pkt_list_decl(n)\
    union {struct vpx_codec_pkt_list head;\
        struct {struct vpx_codec_pkt_list head;\
            struct vpx_codec_cx_pkt    pkts[n];} alloc;}
#define vpx_codec_pkt_list_init(m)\
    (m)->alloc.head.cnt = 0,\
    (m)->alloc.head.max = \
    sizeof((m)->alloc.pkts) / sizeof((m)->alloc.pkts[0])

int
vpx_codec_pkt_list_add(struct vpx_codec_pkt_list *,
                       const struct vpx_codec_cx_pkt *);

const vpx_codec_cx_pkt_t*
vpx_codec_pkt_list_get(struct vpx_codec_pkt_list *list,
                       vpx_codec_iter_t           *iter);


#include <stdio.h>
#include <setjmp.h>
struct vpx_internal_error_info
{
    vpx_codec_err_t  error_code;
    int              has_detail;
    char             detail[80];
    int              setjmp;
    jmp_buf          jmp;
};

static void vpx_internal_error(struct vpx_internal_error_info *info,
                               vpx_codec_err_t                 error,
                               const char                     *fmt,
                               ...)
{
    va_list ap;

    info->error_code = error;
    info->has_detail = 0;

    if (fmt)
    {
        size_t  sz = sizeof(info->detail);

        info->has_detail = 1;
        va_start(ap, fmt);
        vsnprintf(info->detail, sz - 1, fmt, ap);
        va_end(ap);
        info->detail[sz-1] = '\0';
    }
    if (info->setjmp)
        longjmp(info->jmp, info->error_code);
}
#endif

