/*!\file * \brief vpx 画像記述子と、それに関連する操作を記述します * */ #ifdef __cplusplus extern "C" { #endif
#ifndef VPX_IMAGE_H #define VPX_IMAGE_H
/*!\brief 現在の ABI バージョン番号 * * \internal * ABI が変わるような変更をこのファイルに加えた場合は、この値を * 増やさなければなりません。たとえば、型の変更、列挙値の削除や * 再割り当て、構造体のフィールドの追加・削除・並べ替えなどが * ありますが、これらに限りません */ #define VPX_IMAGE_ABI_VERSION (1) /**<\hideinitializer*/
#define VPX_IMG_FMT_PLANAR 0x100 /**< 画像はプレーナー 形式です */ #define VPX_IMG_FMT_UV_FLIP 0x200 /**< メモリー上で V プレーンが U プレーンより前にあります */ #define VPX_IMG_FMT_HAS_ALPHA 0x400 /**< 画像にアルファチャンネルの 成分があります */
/*!\brief サポートしている画像形式のリスト */ typedef enum vpx_img_fmt { VPX_IMG_FMT_NONE, VPX_IMG_FMT_RGB24, /**< 1 ピクセル 24 ビットのパックド RGB */ VPX_IMG_FMT_RGB32, /**< 1 ピクセル 32 ビットのパックド 0RGB */ VPX_IMG_FMT_RGB565, /**< 1 ピクセル 16 ビット、565 */ VPX_IMGFMT_RGB555, /**< 1 ピクセル 16 ビット、555 */ VPX_IMG_FMT_UYVY, /**< UYVY のパックド YUV */ VPX_IMG_FMT_YUY2, /**< YUYV のパックド YUV */ VPX_IMG_FMT_YVYU, /**< YVYU のパックド YUV */ VPX_IMG_FMT_BGR24, /**< 1 ピクセル 24 ビットのパックド BGR */ VPX_IMG_FMT_RGB32_LE, /**< 32 ビットのパックド BGR0 */ VPX_IMG_FMT_ARGB, /**< 32 ビットのパックド ARGB、alpha=255 */ VPX_IMG_FMT_ARGB_LE, /**< 32 ビットのパックド BGRA、alpha=255 */ VPX_IMG_FMT_RGB565_LE, /**< 1 ピクセル 16 ビット、 gggbbbbb rrrrrggg */ VPX_IMG_FMT_RGB555_LE, /**< 1 ピクセル 16 ビット、 gggbbbbb 0rrrrrgg */ VPX_IMG_FMT_YV12 = VPX_IMG_FMT_PLANAR | VPX_IMG_FMT_UV_FLIP | 1, /**< プレーナー YVU */ VPX_IMG_FMT_I420 = VPX_IMG_FMT_PLANAR | 2, VPX_IMG_FMT_VPXYV12 = VPX_IMG_FMT_PLANAR | VPX_IMG_FMT_UV_FLIP | 3, /** < vpx 色空間のプレーナー 4:2:0 形式 */ VPX_IMG_FMT_VPXI420 = VPX_IMG_FMT_PLANAR | 4 /** < vpx 色空間のプレーナー 4:2:0 形式 */ } vpx_img_fmt_t; /**< enum vpx_img_fmt の別名 */
#if !defined(VPX_CODEC_DISABLE_COMPAT) || !VPX_CODEC_DISABLE_COMPAT /** \deprecated #VPX_IMG_FMT_PLANAR を使用してください */ #define IMG_FMT_PLANAR VPX_IMG_FMT_PLANAR /** \deprecated #VPX_IMG_FMT_UV_FLIP を使用してください */ #define IMG_FMT_UV_FLIP VPX_IMG_FMT_UV_FLIP /** \deprecated #VPX_IMG_FMT_HAS_ALPHA を使用してください */ #define IMG_FMT_HAS_ALPHA VPX_IMG_FMT_HAS_ALPHA
/*!\brief サポートしている画像形式の非推奨のリスト * \deprecated 新しいコードでは #vpx_img_fmt を使用すべきです */ #define img_fmt vpx_img_fmt /*!\brief enum img_fmt の別名。 * \deprecated 新しいコードでは #vpx_img_fmt_t を使用すべきです */ #define img_fmt_t vpx_img_fmt_t
/** \deprecated #VPX_IMG_FMT_NONE を使用してください */ #define IMG_FMT_NONE VPX_IMG_FMT_NONE /** \deprecated #VPX_IMG_FMT_RGB24 を使用してください */ #define IMG_FMT_RGB24 VPX_IMG_FMT_RGB24 /** \deprecated #VPX_IMG_FMT_RGB32 を使用してください */ #define IMG_FMT_RGB32 VPX_IMG_FMT_RGB32 /** \deprecated #VPX_IMG_FMT_RGB565 を使用してください */ #define IMG_FMT_RGB565 VPX_IMG_FMT_RGB565 /** \deprecated #VPX_IMG_FMT_RGB555 を使用してください */ #define IMG_FMT_RGB555 VPX_IMG_FMT_RGB555 /** \deprecated #VPX_IMG_FMT_UYVY を使用してください */ #define IMG_FMT_UYVY VPX_IMG_FMT_UYVY /** \deprecated #VPX_IMG_FMT_YUY2 を使用してください */ #define IMG_FMT_YUY2 VPX_IMG_FMT_YUY2 /** \deprecated #VPX_IMG_FMT_YVYU を使用してください */ #define IMG_FMT_YVYU VPX_IMG_FMT_YVYU /** \deprecated #VPX_IMG_FMT_BGR24 を使用してください */ #define IMG_FMT_BGR24 VPX_IMG_FMT_BGR24 /**< \deprecated #VPX_IMG_FMT_RGB32_LE を使用してください */ #define IMG_FMT_RGB32_LE VPX_IMG_FMT_RGB32_LE /** \deprecated #VPX_IMG_FMT_ARGB を使用してください */ #define IMG_FMT_ARGB VPX_IMG_FMT_ARGB /** \deprecated #VPX_IMG_FMT_ARGB_LE を使用してください */ #define IMG_FMT_ARGB_LE VPX_IMG_FMT_ARGB_LE /** \deprecated #VPX_IMG_FMT_RGB565_LE を使用してください */ #define IMG_FMT_RGB565_LE VPX_IMG_FMT_RGB565_LE /** \deprecated #VPX_IMG_FMT_RGB555_LE を使用してください */ #define IMG_FMT_RGB555_LE VPX_IMG_FMT_RGB555_LE /** \deprecated #VPX_IMG_FMT_YV12 を使用してください */ #define IMG_FMT_YV12 VPX_IMG_FMT_YV12 /** \deprecated #VPX_IMG_FMT_I420 を使用してください */ #define IMG_FMT_I420 VPX_IMG_FMT_I420 /** \deprecated #VPX_IMG_FMT_VPXYV12 を使用してください */ #define IMG_FMT_VPXYV12 VPX_IMG_FMT_VPXYV12 /** \deprecated #VPX_IMG_FMT_VPXI420 を使用してください */ #define IMG_FMT_VPXI420 VPX_IMG_FMT_VPXI420 #endif /* VPX_CODEC_DISABLE_COMPAT */
/**\brief 画像記述子 */ typedef struct vpx_image { vpx_img_fmt_t fmt; /**< 画像形式 */
/* 画像の格納寸法 */ unsigned int w; /**< 格納された画像の幅 */ unsigned int h; /**< 格納された画像の高さ */
/* 画像の表示寸法 */ unsigned int d_w; /**< 表示される画像の幅 */ unsigned int d_h; /**< 表示される画像の高さ */
/* 色差のサブサンプリング情報 */ unsigned int x_chroma_shift; /**< サブサンプリングの次数、X */ unsigned int y_chroma_shift; /**< サブサンプリングの次数、Y */
/* 画像データのポインター。 */ #define VPX_PLANE_PACKED 0 /**< すべてのパックド形式で使用 */ #define VPX_PLANE_Y 0 /**< Y（輝度）プレーン */ #define VPX_PLANE_U 1 /**< U（色差）プレーン */ #define VPX_PLANE_V 2 /**< V（色差）プレーン */ #define VPX_PLANE_ALPHA 3 /**< A（透明度）プレーン */ #if !defined(VPX_CODEC_DISABLE_COMPAT) || !VPX_CODEC_DISABLE_COMPAT #define PLANE_PACKED VPX_PLANE_PACKED #define PLANE_Y VPX_PLANE_Y #define PLANE_U VPX_PLANE_U #define PLANE_V VPX_PLANE_V #define PLANE_ALPHA VPX_PLANE_ALPHA #endif unsigned char *planes[4]; /**< 各プレーンの左上のピクセルへの q ポインター */ int stride[4]; /**< 各プレーンの行間のストライド */
int bps; /**< サンプルあたりのビット数（パックド形式用） */
/* 以下のメンバーは、この画像にデータを関連付けるために * アプリケーションが設定してもかまいません。 */ void *user_priv; /**< この画像にデータを関連付けるために アプリケーションが設定できます。 */
/* 以下のメンバーは非公開として扱うべきです。 */ unsigned char *img_data; /**< 非公開 */ int img_data_owner; /**< 非公開 */ int self_allocd; /**< 非公開 */ } vpx_image_t; /**< struct vpx_image の別名 */
/**\brief 面上の矩形の表現 */ typedef struct vpx_image_rect { unsigned int x; /**< 左端の列 */ unsigned int y; /**< 上端の行 */ unsigned int w; /**< 幅 */ unsigned int h; /**< 高さ */ } vpx_image_rect_t; /**< struct vpx_image_rect の別名 */
/*!\brief 記述子を開き、基になる画像の格納領域を * 割り当てます * * 指定された形式の画像を格納するための記述子を返します。 * 記述子の格納領域はヒープ上に割り当てます。 * * \param[in] img 記述子の格納領域へのポインター。 * このパラメーターが NULL の場合、記述子の * 格納領域はヒープ上に割り当てられます。 * \param[in] fmt 画像の形式 * \param[in] d_w 画像の幅 * \param[in] d_h 画像の高さ * \param[in] align 画像の各行のアラインメント * （バイト単位）。 * * \return 初期化した画像記述子へのポインターを返します。 * img パラメーターが NULL でない場合は、img パラメーターの * 値を返します。 */ vpx_image_t *vpx_img_alloc(vpx_image_t *img, vpx_img_fmt_t fmt, unsigned int d_w, unsigned int d_h, unsigned int align);
/*!\brief 基になる画像の既存の格納領域を使用して、記述子を * 開きます * * 指定された形式の画像を格納するための記述子を返します。記述子の * 格納領域はほかの場所で割り当て済みで、その格納領域を「ラップ」 * する記述子が必要な場合に使用します。 * * \param[in] img 記述子の格納領域へのポインター。 * このパラメーターが NULL の場合、記述子の * 格納領域はヒープ上に割り当てられます。 * \param[in] fmt 画像の形式 * \param[in] d_w 画像の幅 * \param[in] d_h 画像の高さ * \param[in] align 画像の各行のアラインメント * （バイト単位）。 * \param[in] img_data 画像に使用する格納領域 * * \return 初期化した画像記述子へのポインターを返します。 * img パラメーターが NULL でない場合は、img パラメーターの * 値を返します。 */ vpx_image_t *vpx_img_wrap(vpx_image_t *img, vpx_img_fmt_t fmt, unsigned int d_w, unsigned int d_h, unsigned int align, unsigned char *img_data);
/*!\brief 画像の表示部分を示す矩形を設定します * * 画像面上の表示矩形（いわゆるビューポート）を、指定された座標と * サイズに合うように更新します。 * * \param[in] img 画像記述子 * \param[in] x 左端の列 * \param[in] y 上端の行 * \param[in] w 幅 * \param[in] h 高さ * * \return 要求された矩形が有効な場合は 0、それ以外の場合は * 0 以外。 */ int vpx_img_set_rect(vpx_image_t *img, unsigned int x, unsigned int y, unsigned int w, unsigned int h);
/*!\brief 画像を上下に反転します（上と下を入れ替えます） * * 画像が上下逆さまに参照されるように、画像記述子のポインターと * ストライドを調整します。 * * \param[in] img 画像記述子 */ void vpx_img_flip(vpx_image_t *img);
/*!\brief 画像記述子を閉じます * * 画像記述子に関連付けられた、割り当て済みの格納領域をすべて * 解放します。 * * \param[in] img 画像記述子 */ void vpx_img_free(vpx_image_t *img);
#endif #ifdef __cplusplus } #endif

